@test
def test_normality():
    r = st.skewtest(B)
    assert close([r.statistic, r.pvalue], skt)
    r = st.kurtosistest(B)
    assert close([r.statistic, r.pvalue], kut)
    r = st.normaltest(B)
    assert close([r.statistic, r.pvalue], nt)
    r = st.skewtest(B, alternative='less')
    assert close([r.statistic, r.pvalue], skt_l)
    r = st.kurtosistest(x, alternative='greater')
    assert close([r.statistic, r.pvalue], kut_g)
    r2 = st.normaltest(B.reshape(8, 5), axis=0)
    assert close(r2.statistic, nt_ax[0])
    assert close(r2.pvalue, nt_ax[1])
    r = st.jarque_bera(B)
    assert close([r.statistic, r.pvalue], jb)
test_normality()

@test
def test_chisquare():
    obs = np.array([16., 18., 16., 14., 12., 12.])
    ex = np.array([16., 16., 16., 16., 16., 8.])
    out = []
    r = st.chisquare(obs)
    out += [r.statistic, r.pvalue]
    r = st.chisquare(obs, ex)
    out += [r.statistic, r.pvalue]
    r = st.chisquare(obs, ddof=1)
    out += [r.statistic, r.pvalue]
    for lam in ['log-likelihood', 'freeman-tukey', 'mod-log-likelihood', 'neyman', 'cressie-read']:
        r = st.power_divergence(obs, ex, lambda_=lam)
        out += [r.statistic, r.pvalue]
    r = st.power_divergence(obs, ex, lambda_=1.5)
    out += [r.statistic, r.pvalue]
    assert close(out, chi)
    r2 = st.chisquare(np.array([[16., 18.], [16., 14.], [12., 12.]]))
    assert close(r2.statistic, chi_ax[0])
    assert close(r2.pvalue, chi_ax[1])
test_chisquare()

@test
def test_ttest_stats_rank():
    out = []
    for ev in [True, False]:
        for alt in ['two-sided', 'less', 'greater']:
            r = st.ttest_ind_from_stats(15.0, 2.0, 13, 13.5, 3.1, 11, equal_var=ev, alternative=alt)
            out += [r.statistic, r.pvalue]
    assert close(out, tfs)
    b = (x > 3.5).astype(float)
    r = st.pointbiserialr(b, y)
    assert close([r.statistic, r.pvalue], pbs)
    out = []
    for alt in ['two-sided', 'less', 'greater']:
        r1 = st.ranksums(x, y[:9], alternative=alt)
        out += [r1.statistic, r1.pvalue]
        r2 = st.brunnermunzel(x, y[:9], alternative=alt)
        out += [r2.statistic, r2.pvalue]
    r2 = st.brunnermunzel(x, y[:9], distribution='normal')
    out += [r2.statistic, r2.pvalue]
    assert close(out, rk)
    r = st.friedmanchisquare(x[:6], y[:6], x[6:])
    assert close([r.statistic, r.pvalue], fr)
    r = st.friedmanchisquare(np.array([1., 2, 3, 4]), np.array([1., 3, 3, 5]), np.array([2., 2, 4, 4]))
    assert close([r.statistic, r.pvalue], fr_t)
    r = st.alexandergovern(x, y[:9], B[:7])
    assert close([r.statistic, r.pvalue], ag)
test_ttest_stats_rank()

@test
def test_kendall_slopes():
    out = []
    for alt in ['two-sided', 'less', 'greater']:
        r = st.kendalltau(x, y, alternative=alt)
        out += [r.statistic, r.pvalue]
    xt = np.round(x)
    yt = np.round(y)
    r = st.kendalltau(xt, yt)
    out += [r.statistic, r.pvalue]
    r = st.kendalltau(xt, yt, variant='c')
    out += [r.statistic, r.pvalue]
    r = st.kendalltau(x, y, method='asymptotic')
    out += [r.statistic, r.pvalue]
    r = st.kendalltau(B, B[::-1] ** 2)
    out += [r.statistic, r.pvalue]
    assert close(out, kt)
    out = []
    t1 = st.theilslopes(y, x)
    out += [t1.slope, t1.intercept, t1.low_slope, t1.high_slope]
    t2 = st.theilslopes(y, x, method='joint', alpha=0.9)
    out += [t2.slope, t2.intercept, t2.low_slope, t2.high_slope]
    t3 = st.theilslopes(B)
    out += [t3.slope, t3.intercept, t3.low_slope, t3.high_slope]
    s1 = st.siegelslopes(y, x)
    out += [s1.slope, s1.intercept]
    s2 = st.siegelslopes(y, x, method='separate')
    out += [s2.slope, s2.intercept]
    assert close(out, slopes)
    ps = np.array([0.01, 0.2, 0.3, 0.04, 0.5])
    out = []
    for m in ['fisher', 'pearson', 'mudholkar_george', 'tippett', 'stouffer']:
        r = st.combine_pvalues(ps, method=m)
        out += [r.statistic, r.pvalue]
    r = st.combine_pvalues(ps, method='stouffer', weights=np.array([1., 2, 3, 4, 5]))
    out += [r.statistic, r.pvalue]
    assert close(out, cp)
test_kendall_slopes()
